const testRoot=process.env.DSH_BRIDGE_TEST_ROOT; if(!testRoot) throw new Error('DSH_BRIDGE_TEST_ROOT is required');
const source='packages/llm-bridge/src/plugin.ts';const hash=()=>createHash('sha256').update(readFileSync(source)).digest('hex');const before=hash();
const home=mkdtempSync(join(resolve(testRoot),'bridge-final-'));
const id='aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee';const route=compileManagedRouteId(id);const sharedRef=compileManagedCredentialRef(id,1);const recordId=compileManagedRecordKey(id,1);
await new FileLlmCredentialStore(home).writeRecord({recordId,secret:'review-only-shared-value'});
const snapshot={catalogRevision:1,policyRevision:1,adapterVersion:'0.1.5-rc.2',defaultModel:{connectionId:id,modelId:'demo'},connections:[{id,revision:1,displayName:'test',enabled:true,backend:'llm-pi-ai',providerConfig:{api:'openai-completions',baseURL:'http://127.0.0.1:9/v1',models:[{id:'demo'}]},auth:{kind:'api-key',credentialRecordId:recordId},createdAt:'2026-09-21T00:00:00Z',updatedAt:'2026-09-21T00:00:00Z'}]};
