const priorSnapshotEnv=process.env.DSH_SPACES_LLM_SNAPSHOT; const priorHomeEnv=process.env.DSH_SPACES_LLM_HOME; process.env.DSH_SPACES_LLM_SNAPSHOT=snapshotPath; process.env.DSH_SPACES_LLM_HOME=home; const ctx=new Context();const settingsPath=join(home,'settings.yaml');const credentialsPath=join(home,'local-credentials.yaml');
const results={before};
try {
 await ctx.plugin(FileSettingsProvider,{path:settingsPath,dshHome:home,watch:false});
 await ctx.plugin(LocalCredentialProvider,{path:credentialsPath,dshHome:home,watch:false});
 await ctx.credentials.set('REVIEW_LOCAL_KEY','review-only-local-value');
 await ctx.plugin(LlmRuntime);await ctx.plugin(PiAi,{providers:{}});await ctx.plugin(AgentDefaultModel,{provider:'composition',model:'baseline'});
 assert.equal(ctx.llm.listProviders().some(p=>p.id===route),false);
 const settingsBefore=existsSync(settingsPath)?readFileSync(settingsPath,'utf8'):null;
 const fiber=await ctx.plugin(bridge.default);
 await new Promise(setImmediate);
 results.providers=ctx.llm.listProviders();
 assert.equal(results.providers.some(p=>p.id===route),true);
 const models=await ctx.llm.listModels(route);assert.ok(models.some(m=>m.id==='demo'));
 assert.deepEqual(ctx.agentDefaultModel.currentSelection(),{provider:route,model:'demo'});
 assert.equal((await ctx.credentials.resolve('REVIEW_LOCAL_KEY')).value,'review-only-local-value');
 assert.equal((await ctx.credentials.resolve(sharedRef)).value,'review-only-shared-value');
 await assert.rejects(async()=>ctx.credentials.set(sharedRef,'blocked-test-value'),{code:LLM_ERROR.SHARED_CONNECTION_READ_ONLY});
 await assert.rejects(async()=>ctx.settings.update('llm-pi-ai',{providers:{[route]:{baseURL:'http://127.0.0.1:8'}}}),{code:LLM_ERROR.SHARED_CONNECTION_READ_ONLY});
 const settingsAfter=existsSync(settingsPath)?readFileSync(settingsPath,'utf8'):null;assert.equal(settingsAfter,settingsBefore);
 results.modelFound=true;results.defaultProjected=true;results.localDelegation=true;results.sharedCredentialReadOnly=true;results.noProviderPersist=true;
 await fiber.dispose();await new Promise(setImmediate);
 assert.equal(ctx.llm.listProviders().some(p=>p.id===route),false);assert.deepEqual(ctx.agentDefaultModel.currentSelection(),{provider:'composition',model:'baseline'});
 assert.equal((await ctx.credentials.resolve('REVIEW_LOCAL_KEY')).value,'review-only-local-value');
 results.disposedCleanly=true;delete results.providers;
 const later=new Context();
 try {
   await later.plugin(FileSettingsProvider,{path:join(home,'later-settings.yaml'),dshHome:home,watch:false});
   await later.plugin(LocalCredentialProvider,{path:join(home,'later-credentials.yaml'),dshHome:home,watch:false});
   await later.plugin(LlmRuntime);
   const lateBridge=await later.plugin(bridge.default);
   const lateConsumer=await later.plugin(PiAi,{providers:{}});await later.plugin(AgentDefaultModel,{provider:'composition',model:'baseline'});
   await new Promise(setImmediate);assert.ok(later.llm.listProviders().some(p=>p.id===route));
   assert.deepEqual(later.agentDefaultModel.currentSelection(),{provider:route,model:'demo'});
   await lateConsumer.dispose();
   assert.equal(later.settings.describe().some(x=>x.ns==='llm-pi-ai'),false);
   await later.plugin(PiAi,{providers:{}});await new Promise(setImmediate);
   assert.ok(later.llm.listProviders().some(p=>p.id===route));
   await lateBridge.dispose();await new Promise(setImmediate);
   assert.equal(later.llm.listProviders().some(p=>p.id===route),false);
   results.lateConsumerProjection=true;results.consumerOwnsRegistration=true;
 } finally { await later.fiber.dispose(); }
}catch(e){results.failure=e.message;throw e;}finally{await ctx.fiber.dispose();if(priorSnapshotEnv===undefined)delete process.env.DSH_SPACES_LLM_SNAPSHOT; else process.env.DSH_SPACES_LLM_SNAPSHOT=priorSnapshotEnv; if(priorHomeEnv===undefined)delete process.env.DSH_SPACES_LLM_HOME; else process.env.DSH_SPACES_LLM_HOME=priorHomeEnv; results.after=hash();results.sourceStable=results.before===results.after;writeFileSync(join(resolve(testRoot),'bridge-final-direct-results.json'),JSON.stringify(results,null,2));console.log(JSON.stringify(results,null,2));}
